const D = { density:.5, energy:.6, scale:1, speed:1, hue:48, x:.5, y:.5, diaspore:'mixed', style:'photogram', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };
const sty = P.style, dia = P.diaspore;
const DN = cl(P.density,0,1), EN = cl(P.energy,0,1), SC = cl(P.scale,.3,2.4);
const AL = cl(P.alpha,0,100)/100;

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
const SP = cl(P.speed,.05,4);
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;

// ---- wind field: incommensurate, plus real gust events -------------------
const base = .9*Math.sin(T*.61) + .5*Math.sin(T*1.43 + 1.7) + .32*Math.sin(T*2.29)
           + .44*Math.sin(T*.211 + .9);
const squall = .5 + .5*Math.sin(T*.071 + 2.3);              // gusts arrive in fronts
const wind = (.28 + .95*EN)*base*(.35 + .8*squall) + A.lowmid*.9 + K.pulse*.2*K.intensity;
const wx = wind*u*.055 + (P.x - .5)*u*.12;                  // horizontal wind, px/s-ish
const H = P.hue;

// ---- style ---------------------------------------------------------------
let mode;
if (sty === 'plate') mode = 1; else if (sty === 'xray') mode = 2;
else if (sty === 'bokeh') mode = 3; else mode = 0;          // 0 = backlit photogram

// composites politely: additive light, or a soft print-ink pass
if (mode === 1) blendMode(BLEND); else blendMode(ADD);
strokeCap(ROUND); strokeJoin(ROUND);

// ---- 1. pollen streamers: near-neutrally-buoyant clouds ridden by the gust
const nStr = Math.round((2 + DN*4));
noStroke();
for (let k=0;k<nStr;k++) {
  const ph = fr(k*5.3)*6.28;
  const prog = ((T*(.019 + fr(k*2.7)*.026)*(1 + EN*.7) + fr(k*7.1)) % 1);
  const cx = (prog*1.5 - .25)*width;
  const cy = (fr(k*3.9)*.9 + .05 + (P.y - .5)*.5)*height + Math.sin(T*.43 + ph)*u*.07;
  const L = u*(.22 + fr(k*9.1)*.4)*SC, th = u*(.03 + fr(k*4.1)*.05)*SC;
  for (let q=0;q<5;q++) {                                   // stacked veils, all far under the ADD cap
    const av2 = (4 + q*1.4)*.7;
    if (mode === 1) fill(H, 36, 88, 3.6*AL);
    else if (mode === 2) fill(H + 160, 40, 90, 2.2*AL);
    else if (mode === 3) fill(H, 26, 96, 3.2*AL);
    else fill(H, 16, 98, av2*AL);
    push(); translate(cx, cy); rotate(wind*.16 + Math.sin(T*.31 + ph)*.2);
    ellipse(0, 0, L*(1 + q*.22), th*(1 + q*.42)); pop();
  }
}

// ---- 2. pollen motes: fine, advected, almost weightless -------------------
const nMote = Math.round(50 + DN*220);
for (let k=0;k<nMote;k++) {
  const ph = fr(k*1.7)*6.28, sp2 = .5 + fr(k*3.3);
  const drift = ((T*.021*sp2*(1 + EN) + fr(k*5.9) + wind*.012) % 1 + 1) % 1;
  const mx = (drift*1.08 - .04)*width;
  const my = ((fr(k*7.7)*1.06 - .03) + (P.y - .5)*.4)*height
           + Math.sin(T*(.7 + sp2*.5) + ph)*u*.035*(.3 + EN)
           + Math.sin(T*1.9 + ph*2.1)*u*.006;
  const r = u*.0022*SC*(.5 + fr(k*2.3)*1.3);
  const tw = .5 + .5*Math.sin(T*(2.1 + sp2) + ph);          // scintillation
  if (mode === 1) fill(H, 44, 72, (34 + tw*24)*AL);
  else if (mode === 2) fill(H + 150, 36, 96, (16 + tw*14)*AL);
  else if (mode === 3) fill(H, 22, 98, (14 + tw*16)*AL);
  else fill(H, 12, 100, (30 + tw*34)*AL + A.treble*18);
  ellipse(mx, my, r*2*(mode === 3 ? 3.4 : 1), r*2*(mode === 3 ? 3.4 : 1));
}

// ---- 3. pappus parachutes: a separated vortex ring -> very slow fall ------
if (dia !== 'pollen' && dia !== 'samara') {
  const nP = Math.round((6 + DN*30)*(dia === 'pappus' ? 1.5 : 1));
  for (let k=0;k<nP;k++) {
    const ph = fr(k*11.3 + 1)*6.28, sp2 = .45 + fr(k*4.7)*.8;
    const fall = ((T*.026*sp2*(1 + EN*.5) + fr(k*6.1)) % 1);
    const px2 = ((fr(k*2.9)*1.3 - .15) + (P.x - .5)*.3)*width
              + wx*fall*4.5 + Math.sin(T*(.53 + sp2*.4) + ph)*u*.06;
    const py2 = (fall*1.16 - .08)*height + Math.cos(T*.83 + ph)*u*.012;
    const pr = u*.014*SC*(.55 + fr(k*8.3)*.85);
    const spin = ph + T*(.22 + sp2*.3)*(1 + EN);
    const tilt = Math.sin(T*(.9 + sp2*.5) + ph)*.5 + wind*.12;
    const av = cl(fall*9, 0, 1)*cl((1 - fall)*5, 0, 1)*AL;
    if (av < .02) continue;
    push(); translate(px2, py2); rotate(tilt);
    const nF = nP <= 16 ? 11 : (nP <= 26 ? 7 : 5);           // budget: umbrella detail vs count
    if (mode === 1) stroke(H, 22, 46, 52*av);
    else if (mode === 2) stroke(H + 150, 24, 100, 22*av);
    else if (mode === 3) stroke(H, 12, 100, 10*av);
    else stroke(H, 6, 100, 42*av);
    strokeWeight(Math.max(.35, pr*(mode === 3 ? .16 : .045)));
    for (let q=0;q<nF;q++) {
      const a2 = -Math.PI*.5 + (q/(nF-1) - .5)*2.5 + Math.sin(spin)*.09;
      const fl = pr*(.85 + .3*Math.sin(spin*1.7 + q));
      beginShape();
      vertex(0, -pr*.72);
      vertex(Math.cos(a2)*fl*.55, -pr*.72 + Math.sin(a2)*fl*.55);
      vertex(Math.cos(a2)*fl, -pr*.72 + Math.sin(a2)*fl);     // the pappus umbrella
      endShape();
    }
    if (mode !== 3) {
      strokeWeight(Math.max(.3, pr*.05)); line(0, -pr*.72, 0, pr*.5);   // the beak
      noStroke();
      if (mode === 1) fill(H - 12, 42, 40, 72*av); else if (mode === 2) fill(H + 150, 40, 78, 24*av);
      else fill(H + 6, 26, 84, 66*av);
      ellipse(0, pr*.58, pr*.2, pr*.4);                       // the achene
    }
    pop();
  }
}

// ---- 4. samaras: they autorotate — gyroscopic descent, never tumbling ----
if (dia !== 'pollen' && dia !== 'pappus') {
  const nSm = Math.round((3 + DN*14)*(dia === 'samara' ? 1.7 : 1));
  for (let k=0;k<nSm;k++) {
    const ph = fr(k*13.7 + 5)*6.28, sp2 = .5 + fr(k*3.7)*.7;
    const fall = ((T*.05*sp2*(1 + EN*.6) + fr(k*9.3)) % 1);
    const px2 = ((fr(k*5.1)*1.24 - .12) + (P.x - .5)*.3)*width
              + wx*fall*3.4 + Math.sin(T*.61 + ph)*u*.03;
    const py2 = (fall*1.14 - .07)*height;
    const sr = u*.026*SC*(.6 + fr(k*7.9)*.7);
    // autorotation: a steady spin about the vertical, NOT a strobing flip
    const rot = ph + T*(2.6 + sp2*1.6)*(.5 + .6*EN);
    const cone = .55;                                          // the blade's coning angle
    const av = cl(fall*8, 0, 1)*cl((1 - fall)*5, 0, 1)*AL;
    if (av < .02) continue;
    const fore = .34 + .66*Math.abs(Math.cos(rot));            // foreshortening as it turns
    push(); translate(px2, py2);
    for (let b2=0; b2<2; b2++) {
      const dir = b2 ? -1 : 1;
      if (dia === 'samara' && b2 === 1 && (k % 2)) continue;    // some are single-winged
      push(); rotate(Math.sin(rot + b2*Math.PI)*cone + wind*.06);
      scale(dir*fore, 1);
      if (mode === 1) { stroke(H - 8, 40, 38, 46*av); strokeWeight(Math.max(.35, sr*.03));
        fill(H, 34, 70, 62*av); }
      else if (mode === 2) { noStroke(); fill(H + 150, 38, 74, 17*av); }
      else if (mode === 3) { noStroke(); fill(H, 16, 96, 11*av); }
      else { noStroke(); fill(H, 8, 98, 44*av); }
      beginShape(); vertex(0, 0);
      bezierVertex(sr*.55, -sr*.30, sr*1.3, -sr*.16, sr*1.7, sr*.16);
      bezierVertex(sr*1.1, sr*.30, sr*.4, sr*.24, 0, 0);
      endShape(CLOSE);
      if (mode !== 3 && nSm <= 14) {                           // wing venation, budgeted
        stroke(mode === 1 ? H - 10 : H, mode === 1 ? 44 : 10, mode === 1 ? 30 : 100, 30*av);
        strokeWeight(Math.max(.3, sr*.022));
        for (let q=0;q<3;q++) line(sr*.15, 0, sr*(1.1 + q*.2), -sr*.1 + q*sr*.11);
      }
      noStroke();
      if (mode === 1) fill(H - 14, 48, 34, 76*av); else if (mode === 2) fill(H + 150, 44, 66, 22*av);
      else fill(H + 4, 30, 82, 60*av);
      ellipse(sr*.1, 0, sr*.3, sr*.42);                        // the seed body
      pop();
    }
    pop();
  }
}

// ---- 5. spore puffs: rare release events on their own slow clock ---------
const nPuff = 3;
noStroke();
for (let k=0;k<nPuff;k++) {
  const cyc = T*(.035 + fr(k*17.3)*.02) + fr(k*4.3)*3;
  const ev = cyc - Math.floor(cyc);                            // 0..1 through this puff's life
  if (ev > .55) continue;
  const e2 = ev/.55;
  const gen = Math.floor(cyc);
  const ox = fr(k*3.1 + gen*7.7)*width, oy = (.2 + fr(k*5.9 + gen*2.3)*.7)*height;
  const n2 = 22;
  for (let q=0;q<n2;q++) {
    const a2 = fr(q*2.7 + k*11.1 + gen)*6.28;
    const spd = .3 + fr(q*5.3 + k*3.7 + gen)*1;
    const rr = u*.20*SC*e2*spd*(.4 + .6*e2);                   // the cloud expands and disperses
    const mx = ox + Math.cos(a2)*rr*1.5 + wx*e2*2.2;
    const my = oy + Math.sin(a2)*rr*.8 - e2*u*.05 + Math.sin(T*1.3 + q)*u*.006;
    const al = (1 - e2)*(1 - e2)*AL;
    if (mode === 1) fill(H - 6, 30, 60, 40*al);
    else if (mode === 2) fill(H + 150, 34, 92, 16*al);
    else if (mode === 3) fill(H, 18, 96, 12*al);
    else fill(H, 10, 100, 34*al);
    const r = u*.004*SC*(.5 + fr(q*7.1 + k)*1.2)*(mode === 3 ? 2.6 : 1);
    ellipse(mx, my, r*2, r*2);
  }
}
blendMode(BLEND);
